begin require"prism";rescue LoadError;require"ripper";end;module Rails;class SourceAnnotationExtractor;class ParserExtractor<Struct.new(:pattern);if defined?(Prism);def annotations(file)result=Prism.parse_file(file);return [] unless result.success?;result.comments.filter_map do |comment|Annotation.new(comment.location.start_line,$1,$2) if comment.location.slice=~pattern;end;end;else class Parser<Ripper;attr_reader:comments,:pattern;def initialize(source,pattern:)super(source);@pattern=pattern;@comments=[];end;def on_comment(value)@comments<<Annotation.new(lineno,$1,$2) if value=~pattern;end;end;def annotations(file)contents=File.read(file,encoding:Encoding::BINARY);parser=Parser.new(contents,pattern:pattern).tap(&:parse);parser.error?? []: parser.comments;end;end;end;class PatternExtractor<Struct.new(:pattern);def annotations(file)lineno=0;File.readlines(file,encoding:Encoding::BINARY).inject([]) do |list,line|lineno+=1;next list unless line=~pattern;list<<Annotation.new(lineno,$1,$2);end;end;end;class Annotation<Struct.new(:line,:tag,:text);def self.directories;@@directories||= %w(app config db lib test);end;def self.register_directories(*dirs)directories.push(*dirs);end;def self.tags;@@tags||= %w(OPTIMIZE FIXME TODO);end;def self.register_tags(*additional_tags)tags.push(*additional_tags);end;def self.extensions;@@extensions||={};end;def self.register_extensions(*exts,&block)extensions[/\.(#{exts.join("|")})$/]=block;end;register_extensions("builder","rb","rake","ruby") do |tag|ParserExtractor.new(/#\s*(#{tag}):?\s*(.*)$/);end;register_extensions("yml","yaml") do |tag|PatternExtractor.new(/#\s*(#{tag}):?\s*(.*)$/);end;register_extensions("css","js") do |tag|PatternExtractor.new(/\/\/\s*(#{tag}):?\s*(.*)$/);end;register_extensions("erb") do |tag|PatternExtractor.new(/<%\s*#\s*(#{tag}):?\s*(.*?)\s*%>/);end;def to_s(options={})s=+"[#{line.to_s.rjust(options[:indent])}] ";s<<"[#{tag}] " if options[:tag];s<<text;end;end;def self.enumerate(tag=nil,options={})tag||=Annotation.tags.join("|");extractor=new(tag);dirs=options.delete(:dirs)||Annotation.directories;extractor.display(extractor.find(dirs),options);end;attr_reader:tag;def initialize(tag)@tag=tag;end;def find(dirs)dirs.inject({}){|h,dir|h.update(find_in(dir))};end;def find_in(dir)results={};Dir.glob("#{dir}/*") do |item|next if File.basename(item).start_with?(".");if File.directory?(item);results.update(find_in(item));else extension=Annotation.extensions.detect do |regexp,_block|regexp.match(item);end;if extension;pattern=extension.last.call(tag);next unless pattern;pattern=PatternExtractor.new(pattern) if pattern.is_a?(Regexp);annotations=pattern.annotations(item);results.update(item=>annotations) if annotations.any?;end;end;end;results;end;def display(results,options={})options[:indent]=results.flat_map{|f,a|a.map(&:line)}.max.to_s.size;results.keys.sort.each do |file|puts"#{file}:";results[file].each do |note|puts"  * #{note.to_s(options)}";end;puts;end;end;end;end
